/*	Re-validate before publishing. Nothing posted is trusted, and publishing is the only
	irreversible thing this automation does.
	Role names come from config, never hardcoded	*/

const cfg = $('Config').first().json;
const sub = $('Extract submission').first().json;
const event = ($json.data || {}).node || null;

const staffList = (((event || {}).staff || {}).edges || []).map(e => e.node);
const coordRole = String(cfg.COORDINATOR_ROLE_NAME).trim();
const clicker = staffList.find(s => s.contact && s.contact.id === sub.contactId) || null;
const isCoordinator = clicker !== null && String((clicker.staffRole || {}).name || '').trim() === coordRole;

/*	The opt out field. Ticked means the coordinator wants publishing left alone,
	so this page refuses rather than overriding their setting	*/
const suppressKey = String(cfg.SUPPRESS_PUBLISH_FIELD_KEY).trim();
const trueValues = String(cfg.CHECKBOX_TRUE_VALUES).split(',').map(v => v.trim().toLowerCase());
let suppressed = false;

for (const cf of ((event || {}).customFieldValues || [])) {
	if (String(cf.definitionKey || '') !== suppressKey) { continue; }
	suppressed = trueValues.indexOf(String(cf.value === null || cf.value === undefined ? '' : cf.value).trim().toLowerCase()) !== -1;
}

const esc = (v) => String(v === null || v === undefined ? '' : v)
	.split('&').join('&amp;').split('<').join('&lt;').split('>').join('&gt;').split('"').join('&quot;');

const page = (title, body) => '<!DOCTYPE html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>' + esc(title) + '</title><style>' + cfg.BRAND_CSS + '</style></head><body><header class="masthead"><p>' + esc(cfg.BRAND_NAME) + '</p></header><main>' + body + '</main></body></html>';

const NOOP = 'query NoOp { __typename }';

/*	Something is genuinely wrong, so it ends by pointing at a human	*/
const refuse = (title, heading, message) => [{ json: {
	valid: false,
	html: page(title, '<h1>' + esc(heading) + '</h1><div class="notice error"><p>' + esc(message) + '</p></div><p>Please reply to the email you came from and someone will help.</p>'),
	publishMutation: NOOP,
	notifyMutation: NOOP
} }];

/*	Everything is in order and there is simply nothing to do, so no offer of help	*/
const closeOff = (title, heading, message) => [{ json: {
	valid: false,
	html: page(title, '<h1>' + esc(heading) + '</h1><div class="notice"><p>' + esc(message) + '</p></div><p>You can close this page.</p>'),
	publishMutation: NOOP,
	notifyMutation: NOOP
} }];

if (!event) { return refuse('Event not found', 'We could not open this event', 'The link may be incomplete, or the event may no longer exist.'); }

if (!isCoordinator) {
	return refuse('Only the ' + coordRole + ' can publish', 'Only the ' + coordRole + ' can publish this event', 'Publishing is done by the ' + coordRole + ' named on the event. If you think that should be you, somebody can add you.');
}

if (suppressed) {
	return closeOff('Publishing is switched off', 'Publishing is switched off for this event', 'Somebody has asked for this one to be published in Administrate by hand, so this page will not do it.');
}

/*	Idempotent. Publishing twice would re-notify everybody	*/
if (String(event.lifecycleState || '') !== 'draft') {
	return closeOff('Already published', esc(event.title), 'This event is already ' + String(event.lifecycleState) + '. Nothing has been changed.');
}

/*	Everybody running the event, which is everybody staffed except the coordinator.
	Read from the event rather than assuming a role name, so it works whatever you
	call them	*/
const running = staffList.filter(s => String((s.staffRole || {}).name || '').trim() !== coordRole);
const instructorIds = running.map(s => s.id);
const notifyWanted = String(sub.notify || '') === 'yes' && instructorIds.length > 0;

const confirmation = notifyWanted
	? '<p>' + running.length + (running.length === 1 ? ' person has' : ' people have') + ' been told the event is going ahead.</p>'
	: '<p>Nobody was notified, so let them know yourself if they are expecting to hear.</p>';

return [{ json: {
	valid: true,
	eventId: event.id,
	eventTitle: String(event.title || ''),
	notify: notifyWanted,
	instructorCount: running.length,
	publishMutation: 'PUBLISH',
	notifyMutation: notifyWanted ? 'NOTIFY' : NOOP,
	instructorIds: instructorIds,
	logMessage: 'Event published by ' + clicker.contact.firstName + ' ' + clicker.contact.lastName + '. ' + (notifyWanted ? running.length + ' notified.' : 'Nobody notified.'),
	logPayload: JSON.stringify({ eventId: event.id, publishedBy: clicker.contact.id, notified: notifyWanted, instructorIds: instructorIds }),
	html: page('Event published', '<h1>' + esc(event.title) + ' is published</h1><div class="notice"><p>The event is now live in Administrate.</p></div>' + confirmation + '<p>You can close this page.</p>')
} }];

/*	The publish link in the staffing complete email carries a random token saved per event
	by 40 Response Handler. A newer completion email replaces it, so older links expire.
	Nothing is shown about the event without a matching token. Nothing is written here	*/

const cfg = $('Config').first().json;
const link = $('Extract submission').first().json;
const rows = $input.all().map((item) => item.json).filter((row) => row && row.event_id);
const row = rows.find((r) => String(r.event_id) === String(link.eventId)) || null;

/*	Compares in constant time, so response timing does not leak how much of a guess
	was right. An empty token never matches	*/
const sameToken = (expected, given) => {
	const a = String(expected || '');
	const b = String(given || '');
	if (a === '' || b === '' || a.length !== b.length) { return false; }
	let diff = 0;
	for (let i = 0; i < a.length; i++) { diff = diff | (a.charCodeAt(i) ^ b.charCodeAt(i)); }
	return diff === 0;
};

const esc = (v) => String(v === null || v === undefined ? '' : v)
	.split('&').join('&amp;').split('<').join('&lt;').split('>').join('&gt;').split('"').join('&quot;');

const page = (title, body) => '<!DOCTYPE html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>' + esc(title) + '</title><style>' + cfg.BRAND_CSS + '</style></head><body><header class="masthead"><p>' + esc(cfg.BRAND_NAME) + '</p></header><main>' + body + '</main></body></html>';

const valid = String(link.eventId || '') !== '' && String(link.contactId || '') !== '' && row !== null && sameToken(row.token, link.linkToken);
const heading = 'This link is invalid or has expired';

return [{ json: {
	valid: valid,
	html: valid ? '' : page(heading, '<h1>' + esc(heading) + '</h1><div class="notice error"><p>' + 'The event was not published and nothing has changed. This publish link is not valid any more.' + '</p></div><p>Use the link in the most recent staffing complete email, or publish the event in Administrate.</p>')
} }];
